{
  "findings": [
    {
      "title": "Inconsistent AE collection duration: 100 days vs 100 days after last dose",
      "page": 25,
      "quote": "AEs and concomitant medications data will be collected until 100 days (±7 days) after the last dose of study drug (vidutolimod or cemiplimab) or until an alternative anticancer treatment is initiated, or until overall End of Clinical Trial (Section 3.4), whichever occurs first. The 100DFU should occur 100 days (±7 days) from the last study treatment (vidutolimod or cemiplimab) and may be conducted at the study site or via phone.",
      "severity": "minor"
    },
    {
      "title": "Inconsistent PTFU duration: 18 months vs Q3mo until progression",
      "page": 25,
      "quote": "Posttreatment follow-up (PTFU) will be conducted Q3mo (±2 weeks) for all subjects who discontinue study treatment but have not met criteria for study discontinuation. These subjects should remain on study and receive disease assessments Q3mo, until disease progression or discontinuation of PTFU for any reason. For an individual subject, the maximum duration of PTFU is 18 months.",
      "severity": "minor"
    },
    {
      "title": "Inconsistent vidutolimod dosing schedule: W10D1+ vs Q3W",
      "page": 25,
      "quote": "Q3W dosing (W10D1+): A window of ±3 days is permitted for vidutolimod dosing from W10D1 throughout the study.",
      "severity": "minor"
    },
    {
      "title": "Inconsistent pregnancy test timing: W1D1 vs within 24 hours prior to start",
      "page": 25,
      "quote": "For WOCBP, a serum pregnancy test and FSH are completed at Screening and W1D1. WOCBP must have a negative serum or urine pregnancy test (minimum sensitivity 25 IU/L or equivalent units of human chorionic gonadotropin) within 24 hours prior to the start of study treatment.",
      "severity": "minor"
    },
    {
      "title": "Inconsistent pregnancy test requirement: WOCBP vs women with bilateral tubal ligation",
      "page": 25,
      "quote": "Pregnancy testing should be performed in women having a bilateral tubal ligation.",
      "severity": "minor"
    },
    {
      "title": "Inconsistent disease assessment schedule: every 9 weeks vs every 12 weeks",
      "page": 26,
      "quote": "Disease assessments will be performed at screening and predose beginning at W10D1 (-7 days) and repeated every 9 weeks (-7 days) (eg, W19D1, W28D1, etc). ... Disease assessments may be performed every 12 weeks for subjects with a response continuing more than 1 year.",
      "severity": "minor"
    },
    {
      "title": "Inconsistent screening window: 45 days vs 30 days",
      "page": 26,
      "quote": "Informed consent must be provided before the initiation of screening procedures and must be obtained within 45 days prior to W1D1. All screening assessments must be performed within 30 days prior to W1D1.",
      "severity": "minor"
    },
    {
      "title": "Inconsistent re-screening: ICF signed at re-screen vs some procedures not repeated",
      "page": 26,
      "quote": "Subjects who fail screening may be screened one additional time and an ICF will need to be signed at the re-screen. Some procedures may not need to be repeated if they were previously completed within 30 days prior to W1D1 vidutolimod injection.",
      "severity": "minor"
    },
    {
      "title": "Inconsistent PTFU vs LTSFU: PTFU maximum 18 months vs LTSFU Q3mo",
      "page": 25,
      "quote": "After completing PTFU, subjects go to LTSFU. ... LTSFU will be conducted Q3mo (± 4 weeks) after the EOT visit or the last disease assessment date in PTFU and may occur via phone.",
      "severity": "minor"
    },
    {
      "title": "Inconsistent AE collection: 100 days vs 100 days after last dose",
      "page": 25,
      "quote": "AEs will be assessed from time of consent through 100 days after the last dose of study treatment or until an alternative anticancer treatment is initiated, whichever occurs first.",
      "severity": "minor"
    },
    {
      "title": "Inconsistent vital signs: 4 hours vs 1 hour observation",
      "page": 25,
      "quote": "For the first 6 vidutolimod dosing visits (W1D1 to W6D1), vital signs must be collected prior to the vidutolimod injection (±10 minutes) and at 30-minute (±15 minutes) intervals for 4 hours after vidutolimod injection. Starting at W7D1, observation periods may be reduced to a minimum of 1 hour following vidutolimod injection at the Investigator’s discretion based on the AE profile of the individual subject.",
      "severity": "minor"
    },
    {
      "title": "Inconsistent ECG timing: W3D1 and W7D1 vs W1D1",
      "page": 25,
      "quote": "12-lead ECGs will be obtained at Screening, before the W1D1, W3D1, and W7D1 vidutolimod injections, and at EOT.",
      "severity": "minor"
    }
  ]
}
